import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"家人","description":"焦氏易林注 - 家人","frontmatter":{"title":"家人","description":"焦氏易林注 - 家人"},"headers":[],"relativePath":"classics/jiaoyilin/037.md","filePath":"classics/jiaoyilin/037.md"}'),l={name:"classics/jiaoyilin/037.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h3 id="家人-1" tabindex="-1">家人 <a class="header-anchor" href="#家人-1" aria-label="Permalink to “家人”">​</a></h3><h3 id="家人之乾" tabindex="-1">家人之乾 <a class="header-anchor" href="#家人之乾" aria-label="Permalink to “家人之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>千歲槐根，身多斧瘢。傷夷倒掘，枝葉不存。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為千歲，家人巽為槐，兌為斧，初二三四皆兌形。艮為節、為瘢，二三四五皆艮形，故曰身多斧瘢。巽隕落故曰傷夷，故無枝葉。○瘢，汲古作痕，非，依宋元本。三句宋元作傷癕搗理，依汲古。</p><h3 id="家人之坤" tabindex="-1">家人之坤 <a class="header-anchor" href="#家人之坤" aria-label="Permalink to “家人之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>喭喭諤諤，虎豹相齚。畏懼悚息，終無難惡。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此亦取遇卦《家人》象。家人重離，離正反兌口相對，喭喭諤諤，語多貌，離正反兌相對艮為虎豹，故曰相齚.齚，亦兌象也。坎為畏懼。</p><h3 id="家人之屯" tabindex="-1">家人之屯 <a class="header-anchor" href="#家人之屯" aria-label="Permalink to “家人之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>娶於薑呂，駕迎新婦。少齊在門，夫子歡喜。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為娶，伏巽為薑呂、為震婦、為少齊。坤為門，震為夫子、為喜，《左傳昭三年》：&quot;少薑有寵於晉，謂之少齊&quot;。</p><h3 id="家人之蒙" tabindex="-1">家人之蒙 <a class="header-anchor" href="#家人之蒙" aria-label="Permalink to “家人之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>膏壤肥澤，民人孔樂。宜利居止，長安富有。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坎為膏澤，坤為壤、為民人，互震為孔樂，艮止故利居。坤為安，震為長，故曰長安，坤多故曰富有。</p><h3 id="家人之需" tabindex="-1">家人之需 <a class="header-anchor" href="#家人之需" aria-label="Permalink to “家人之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>主有聖德，上配太極。皇靈建中，授我以福。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為聖、為主，乾天故配太極，乾為帝、為皇、為福，坎為中。○主，元本訛坐，從宋本、汲古。《詩大雅》：&quot;克配彼天&quot;、&quot;莫匪爾極&quot;，《書》：&quot;建中於民，斂時五福&quot;。</p><h3 id="家人之訟" tabindex="-1">家人之訟 <a class="header-anchor" href="#家人之訟" aria-label="Permalink to “家人之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>耄老懞鈍，不見東西。少者弗慕，君不與謀。懸輿致仕，退歸里居。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為老，離東坎西，坎隱故不見東西。兌為少，乾為君，今兌口向下，與乾君背，故曰弗慕、曰君不與謀。伏坤為輿，在上故曰懸輿。艮為官、為仕，伏震艮覆，故曰致仕。震為歸，坤為裡。</p><h3 id="家人之師" tabindex="-1">家人之師 <a class="header-anchor" href="#家人之師" aria-label="Permalink to “家人之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>三狂北行，道逢大狼。暮宿患宅，為禍堪傷。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為狂，數三，故曰三狂，坤北故曰北行。震為行、為道，艮為狼，狼首向內，與坎室連，故曰患宅。坤為暮，坎為宿、為患、為室，故曰暮宿患宅。○堪，汲古作所，依宋元本。</p><h3 id="家人之比" tabindex="-1">家人之比 <a class="header-anchor" href="#家人之比" aria-label="Permalink to “家人之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>更旦初歲，振除禍敗。新衣元服，拜受利福。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>震為旦，震覆，故曰更旦。坤為歲、為禍敗，艮手故曰振除禍敗。坤為衣服，坤黑，故曰元服。艮手為拜，坤為受，一陽居五，群陰拱之，故雲利福指五。</p><h3 id="家人之小畜" tabindex="-1">家人之小畜 <a class="header-anchor" href="#家人之小畜" aria-label="Permalink to “家人之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>杲杲白日，為月所食。損上毀下，鄭昭出走。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>互離為日，兌為月，兌侵入離體之半，故曰日為月所食。巽為損，在上故曰損上，兌毀折在下，故曰毀下。伏坎為鄭，離為昭，鄭昭名忽，桓十一年出奔。○下。汲古作上。依宋本。</p><h3 id="家人之履" tabindex="-1">家人之履 <a class="header-anchor" href="#家人之履" aria-label="Permalink to “家人之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>君子失意，小人得志。亂擾並作，姦邪充塞。雖有百堯，顛不可救。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。艮為君子，在下故失意。坤為小人，在上故得志。坎為失、為志，坤為亂、為姦邪，震為帝，坤為百，故曰百堯。正反震故曰顛。○擾，汲古作憂，依宋元本。</p><h3 id="家人之泰" tabindex="-1">家人之泰 <a class="header-anchor" href="#家人之泰" aria-label="Permalink to “家人之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>仁德利洽，恩及異域。澤被殊方，福慶隱伏。作蠶不織，寒無所得。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾為仁德，兌為恩澤，坤為方域，乾為福慶，在下故隱伏。巽為蠶，巽覆故不織。乾為寒。○利，汲古作擾，依宋本。</p><h3 id="家人之否" tabindex="-1">家人之否 <a class="header-anchor" href="#家人之否" aria-label="Permalink to “家人之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>東求金玉，反得弊石。名曰無宜，字曰醜惡，眾所賤惡。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>伏震為東，艮為求，乾為金玉，艮為石，互巽故曰弊石。艮為名，坤為字、為醜惡、為眾、為惡、為賤。</p><h3 id="家人之同人" tabindex="-1">家人之同人 <a class="header-anchor" href="#家人之同人" aria-label="Permalink to “家人之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>擊鼓合戰，士怯叛亡。威令不行，敗我成功。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為鼓、為戰、為士，坤柔故曰怯。震為往、為亡、為威令，坤閉故不行，坤喪故敗。</p><h3 id="家人之大有" tabindex="-1">家人之大有 <a class="header-anchor" href="#家人之大有" aria-label="Permalink to “家人之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>仲春孟夏，和氣所舍。生我嘉福，國無殘賊。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>伏《震》，與坎連故曰仲春，巽為孟夏。坎為和。舍，發也，伏艮為國，坎為賊，首二句言春夏之交，陽和之氣發生也。用《家人》象。</p><h3 id="家人之謙" tabindex="-1">家人之謙 <a class="header-anchor" href="#家人之謙" aria-label="Permalink to “家人之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>尹氏伯奇，父子生離。無罪被辜，長舌為災。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為伯、為父，又為子，正反震相背故曰生離。坤為罪辜，兌為舌，震形似兌而長故曰長舌。坤為災。伯奇，尹吉甫子為後母所讒，被放逐。○生，汲古作相，依宋元本。</p><h3 id="家人之豫" tabindex="-1">家人之豫 <a class="header-anchor" href="#家人之豫" aria-label="Permalink to “家人之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>五榖不熟，民苦困急。駕之新邑，嘉樂有得。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為榖，坎納戊，數五，故曰五榖，坤喪故不熟。坤為民，坎為困苦，震為駕、為樂，坤為邑。○五，宋元本作三，依汲古。第二句汲古作困民惡極，樂作禾，均依宋元本。</p><h3 id="家人之隨" tabindex="-1">家人之隨 <a class="header-anchor" href="#家人之隨" aria-label="Permalink to “家人之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>登虛望貧，暮食無飡。長子南戍，與我生分。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為登，艮為虛，《詩》&quot;登彼虛矣&quot;。艮為望，巽隕落，故曰貧。兌為暮、為食，震為長子、為南，艮守故曰南戍。艮為我，正反艮故曰生分。震為生。</p><h3 id="家人之蠱" tabindex="-1">家人之蠱 <a class="header-anchor" href="#家人之蠱" aria-label="Permalink to “家人之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>東市齊魯，南賈荊楚。羽毛齒革，為吾利寶。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽齊兌魯，震為東、為南，巽為市、為賈，震為荊楚，故東市齊魯，南賈荊楚。震為羽毛，兌為齒，艮為革，巽為利，震為寶。</p><h3 id="家人之臨" tabindex="-1">家人之臨 <a class="header-anchor" href="#家人之臨" aria-label="Permalink to “家人之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>節情省欲，賦斂有度。家給人足，公劉以富。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為情慾、為吝嗇，故曰節省。坤為聚，故曰賦斂，坤多，故曰家給人足。坤為輗，震為公，故曰公劉。公劉，周祖也。○斂。宋元本作鈠。依汲古。</p><h3 id="家人之觀" tabindex="-1">家人之觀 <a class="header-anchor" href="#家人之觀" aria-label="Permalink to “家人之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>恭寬信敏，功加四海。闢去不祥，喜來從母。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤柔故曰恭寬，止故信，風散故敏。坤為海，巽數四，風散故功加四海，坤死故不祥，巽伏故避去不祥。伏震為喜，坤為母。</p><h3 id="家人之噬嗑" tabindex="-1">家人之噬嗑 <a class="header-anchor" href="#家人之噬嗑" aria-label="Permalink to “家人之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>張狂妄行，與惡相逢。不得所欲，生我獨兇。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為張狂、為行，遇坎陷，故曰與惡相逢，故曰不得所欲。○行，宋元本作作，依汲古。</p><h3 id="家人之賁" tabindex="-1">家人之賁 <a class="header-anchor" href="#家人之賁" aria-label="Permalink to “家人之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>畫龍頭頸，文章不成。甘言美語，詭辭無名。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>賁，飾也，故曰畫。震為龍，艮為頭頸，離為文章，坎黑而隱伏，故文章不成。三至上正反震，故曰甘言美語，故曰詭辭。艮為名，坎伏故無名。</p><h3 id="家人之剝" tabindex="-1">家人之剝 <a class="header-anchor" href="#家人之剝" aria-label="Permalink to “家人之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>騎龍乘風，上見神公。彭祖受刺，王喬贊通。巫咸就位，拜壽無窮。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>伏乾為龍，坤為風，一陽在上故曰騎乘。乾為神、為公，艮為壽，故曰彭祖，艮陽在上故曰刺。刺，謁札也。王喬，古仙人，亦艮象。巫咸，王逸，《離騷》註：古神巫也，殷中宗之世下降。伏兌為巫。彭祖受刺者，言欲見神公彭祖受謁札；王喬贊通者，言見神公時王喬為通其名也。艮為拜、為壽。○刺，汲古訛制，喬訛高，均依宋元本。</p><h3 id="家人之復" tabindex="-1">家人之復 <a class="header-anchor" href="#家人之復" aria-label="Permalink to “家人之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>溫仁君子，忠孝所在。八國為鄰，禍災不處。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤柔故曰溫仁，曰忠孝。震為君、為子，故曰溫仁君子。震為鄰，坤為國，卦數八，故曰八國為鄰。坤為禍災，震解故不處。○處，汲古作起，依宋元本。</p><h3 id="家人之無妄" tabindex="-1">家人之無妄 <a class="header-anchor" href="#家人之無妄" aria-label="Permalink to “家人之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>威權分離，烏夜徘徊。群蔽月光，大人誅傷。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為威，巽為權，初至四正反震，故曰分離。艮為鳥，伏坤為夜、為群，兌為月，兌伏，故月為坤黑所蔽也。乾為大人，坤殺，故誅傷，此必有故實，或以左氏楚幕有烏及城上有烏，齊師其遁當之，皆不合，俟考。○月，宋元本作日，非，依汲古。</p><h3 id="家人之大畜" tabindex="-1">家人之大畜 <a class="header-anchor" href="#家人之大畜" aria-label="Permalink to “家人之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>學靈三年，仁聖且神。明見善祥，吉喜福慶。鳱鵠知來，告我無憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《漸》，第五句宋元本作神烏來見，汲古烏作鳥，皆依《小畜》之《漸》校。</p><h3 id="家人之頤" tabindex="-1">家人之頤 <a class="header-anchor" href="#家人之頤" aria-label="Permalink to “家人之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>東山辭家，處婦思夫。伊威盈室，長股羸戶。嘆我君子，役日未已。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為東、為夫，艮為山、為室家、為君子，巽為震婦，巽伏，故曰處婦。坤為心、為思，巽為蟲，故曰伊威。《詩傳》：&quot;伊威，委黍也&quot;，陸機雲&quot;生甕底似白魚&quot;。長股，蠨蛸也，詩疏：即長腳小蜘蛛。羸，宋衷易羸豕註：以羸為大索。陸績、虞翻皆讀作縲，長股羸戶者，言蜘蛛作網於戶。元本舊註疑羸為裸，誤之遠矣，巽為股、為長，故曰長股。《詩》&quot;蠨蛸在戶&quot;《傳》&quot;蠨蛸長踦&quot;，是焦詩與毛同也。</p><h3 id="家人之大過" tabindex="-1">家人之大過 <a class="header-anchor" href="#家人之大過" aria-label="Permalink to “家人之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>張頷開口，舌直距齒。然諾不行，政亂無緒。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>兌為口、為頷、為舌、為齒，乾為直，兌為言，正覆兌相背，故曰舌直距齒，曰然諾不行。伏坤為政、為亂，巽為緒。○直距，汲古作宜絕，依宋元本。</p><h3 id="家人之坎" tabindex="-1">家人之坎 <a class="header-anchor" href="#家人之坎" aria-label="Permalink to “家人之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>吹角高邦，有失牛羊。眾民驚惶，敬慎避咎，勑不行殃。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互艮為角、為高邦，震口為吹、為羊，艮為牛，坎為失，故有失牛羊。坎為眾、為民，震為驚，艮為敬慎。○敬，宋元本作警，從汲古。</p><h3 id="家人之離" tabindex="-1">家人之離 <a class="header-anchor" href="#家人之離" aria-label="Permalink to “家人之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>南行出城，世得福祉。王姬歸齊，賴其所欲。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。震為南、為行，艮為城、為世，震為福祉、為王、為姬、為歸，巽為齊。○得，汲古作德，歸作嫁，均依宋元本。王姬嫁齊魯為主在莊元年。</p><h3 id="家人之鹹" tabindex="-1">家人之鹹 <a class="header-anchor" href="#家人之鹹" aria-label="Permalink to “家人之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>心狂志悖，視聰聳類。政令無常，下民多孽。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為心志，震為狂，艮為視，坤為類，艮一陽在坤上，故曰聳類。坤為政，巽為令，二至上正反巽，故曰無常。坤為下民、為孽。○志，宋元本作老，茲依汲古。視聳，汲古作耳從，依宋元本。</p><h3 id="家人之恆" tabindex="-1">家人之恆 <a class="header-anchor" href="#家人之恆" aria-label="Permalink to “家人之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>安上宜官，一日九遷。逾群越等，牧養常山。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。艮為山、為上、為官，乾為日，卦數一，故曰一日，震數九，故曰九遷。坤為群、為等、為牧養，震為遷，故曰逾越。艮為山，坤北故曰常山。常山，北嶽也。</p><h3 id="家人之遯" tabindex="-1">家人之遯 <a class="header-anchor" href="#家人之遯" aria-label="Permalink to “家人之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰嫁女，為王妃後。莊公築館，以尊王母。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>歸於京師，季薑悅喜。詳《屯》之《觀》。莊當為桓，事在桓九年紀季薑歸於京師。○王，汲古作主，非。</p><h3 id="家人之大壯" tabindex="-1">家人之大壯 <a class="header-anchor" href="#家人之大壯" aria-label="Permalink to “家人之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>六甲無子，以喪其戊。五丁本親，庚失曾孫，癸走出門。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾納甲，震為子，兌毀折，乾數六，故曰六甲無子。坎居子，方納戊，六甲始於子，今無子故曰以喪其戊。互兌，納丁，伏巽，卦數五，故曰五丁，乾健震健，兌剛，遠行故不親。震納庚，艮為曾孫，艮覆故曰失。坤上卦納癸，乾為門，震出，大壯五上皆坤爻，在外故曰癸走出門。○以，宋元本作已，從汲古。</p><h3 id="家人之晉" tabindex="-1">家人之晉 <a class="header-anchor" href="#家人之晉" aria-label="Permalink to “家人之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>陰霧不清，濁政亂民。孟秋季夏，水壞我居。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為陰霧、為混濁，坤為政、為民，伏兌為秋，兌與離連，故曰孟秋。上離為夏，離與艮連故曰季夏。坤坎皆為水，艮為居，坎破故曰壞。孟秋季夏用象之精，非夷所思。○秋，汲古作春，是不知象者妄改，依宋元本。</p><h3 id="家人之明夷" tabindex="-1">家人之明夷 <a class="header-anchor" href="#家人之明夷" aria-label="Permalink to “家人之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>騎豚逐羊，不見所望。徑涉虎廬，亡豚失羊。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為騎，坎為豕，震為羊，離為望，坎隱故不見。又豚行緩亦不能及也。艮為虎，艮反與坎室連，故曰虎廬。坤為喪，故曰亡失。○羊，宋元本作羔，依汲古。</p><h3 id="家人之家人" tabindex="-1">家人之家人 <a class="header-anchor" href="#家人之家人" aria-label="Permalink to “家人之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>天命赤烏，與兵徼期。征伐無道，誅其君傲，居止何憂。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>坎為赤，離為烏，巽為命，離為兵戈，伏震為征伐。震為大塗、為君，震伏故曰無道、曰誅其君。坎巽皆為伏，故曰居止。《史記周本紀》：&quot;武王伐紂，有赤烏流於王屋&quot;，首二句謂天以赤烏示瑞，示伐紂之期至也。○天，汲古作王，兵作君，均依宋元本。</p><h3 id="家人之睽" tabindex="-1">家人之睽 <a class="header-anchor" href="#家人之睽" aria-label="Permalink to “家人之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>安床厚褥，不得久宿。棄我喜晏，困於南國。投杼之憂，不成禍災。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>伏《蹇》。艮為床，坎為宿，離為南，艮為國，故曰南國。坎為杼，《戰國策》甘茂曰：昔曾參之母方織，人謂曾參殺人，三告之，其母投杼而走。○得，宋元本作歸，晏作燕，不作弗，依汲古。</p><h3 id="家人之蹇" tabindex="-1">家人之蹇 <a class="header-anchor" href="#家人之蹇" aria-label="Permalink to “家人之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>五方四維，安平不危。利以居止，保有玉女。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎納戊，數五，伏兌，納丁，數四，故曰五方四維。艮為安、為居止，坎為危，艮安故不危。伏兌為女，艮堅故曰玉女。○方，汲古作日，依宋元本。</p><h3 id="家人之解" tabindex="-1">家人之解 <a class="header-anchor" href="#家人之解" aria-label="Permalink to “家人之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>西賈巴蜀，寒雪至轂。欲前不得，復反其室。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎位西，伏巽為賈，巽在西南，故曰巴蜀。坎為寒、為雪、為轂，坎陷故不能前。震為反，坎為室，此為坎西、巽西南之確證。○復反，汲古作反覆，依宋元本。</p><h3 id="家人之損" tabindex="-1">家人之損 <a class="header-anchor" href="#家人之損" aria-label="Permalink to “家人之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>剛柔相呼，二姓為家。霜降既同，惠我以仁。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>兌為剛，互坤為柔，正反震，故曰相呼。坤為姓，數二，故曰二姓。艮為家，坤為霜、為我，震為仁。家，音姑，《荀子大略》篇：&quot;霜降逆女，冰泮殺內&quot;，言嫁娶始於霜降，至冰泮而止。</p><h3 id="家人之益" tabindex="-1">家人之益 <a class="header-anchor" href="#家人之益" aria-label="Permalink to “家人之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>天馬五道，炎火分處。往來上下，相隨哭歌，兇惡如何。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為大塗，艮為天，巽卦數五，故曰天馬五道。《晉書天文志》：&quot;王良，五星，一名天馬&quot;。艮為火，正反艮，故曰分處。震為往，正反震，故曰往來上下。震為歌，震之反則哭矣。《中孚六二》雲：&quot;或泣或歌&quot;，林所本也。坤為兇惡。○宋元本第三句下多&quot;住又亡駒，衣柔巾麻&quot;二句，定為衍文，依汲古刪。炎火，汲古訛夾大，如何訛好向，均依宋元本。</p><h3 id="家人之夬" tabindex="-1">家人之夬 <a class="header-anchor" href="#家人之夬" aria-label="Permalink to “家人之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>出門懷憂，東上禍丘。與兇相遇，自為災患。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。坤為門、為憂禍、為兇災，艮為丘，乾坤納甲乙，故曰東上禍丘。</p><h3 id="家人之姤" tabindex="-1">家人之姤 <a class="header-anchor" href="#家人之姤" aria-label="Permalink to “家人之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>西行求玉，冀得隋璞。反見兇惡，使我驚惑。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為行、為玉璞，坤為兇惡、為惑，震為驚。○隋，宋元本訛隨，依汲古。</p><h3 id="家人之萃" tabindex="-1">家人之萃 <a class="header-anchor" href="#家人之萃" aria-label="Permalink to “家人之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>出入無妄，動作失利。銜憂懷禍，使我多悴。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>伏震為出，巽為入，坤喪兌毀，故無妄。妄，西漢人皆讀為望。兌口為銜，坤為憂禍、為我。○入，汲古作門，妄作至，非，依宋元本。</p><h3 id="家人之升" tabindex="-1">家人之升 <a class="header-anchor" href="#家人之升" aria-label="Permalink to “家人之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>高樓無柱，顛僵不久。紂失三仁，身死牧野。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為重，故曰高樓，本弱故無柱，巽隕故顛僵，坤惡故曰紂。震為仁，數三，故曰三仁，兌毀折，故失三仁。坤為身、為野、為養，故曰牧野。坤殺故曰身死。</p><h3 id="家人之困" tabindex="-1">家人之困 <a class="header-anchor" href="#家人之困" aria-label="Permalink to “家人之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>避禍逃殃，身全不傷。高位疾顛，華落墜亡。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎為災，故曰禍殃，坎隱故曰避逃。伏艮為身，在外，故曰身全不傷。艮為位，在上故曰高位，巽隕故顛。兌為華，巽落故曰墜亡。○墜亡，宋本作墮兇，元本作墮亡，依汲古。</p><h3 id="家人之井" tabindex="-1">家人之井 <a class="header-anchor" href="#家人之井" aria-label="Permalink to “家人之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>張牙反目，怒齚作怒。狂馬撓犬，道驚傷軫。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>兌為牙，離為目，坎兩半離相背，故曰反目。兌為齚，伏震為怒、為狂，伏艮為犬，艮止，故狂馬竟為犬所撓，而車驚傷軫也。震為道、為驚，兌為傷軫象，或屬坎。○作，汲古作忿，依宋元本。撓，宋元本作燒，依汲古。</p><h3 id="家人之革" tabindex="-1">家人之革 <a class="header-anchor" href="#家人之革" aria-label="Permalink to “家人之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>泉涸龍憂，箕子為奴。乾叔隕命，殷破其家。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《剝》。</p><h3 id="家人之鼎" tabindex="-1">家人之鼎 <a class="header-anchor" href="#家人之鼎" aria-label="Permalink to “家人之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>向食飲酒，嘉賓聚會。羊大豬，君子饒有。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎為酒，兌口為飲，震為嘉賓，坤為眾，故曰嘉賓聚會。兌為羊，巽為豕，與乾連，乾為牡、為大，故曰羊大豬。艮為君子。</p><h3 id="家人之震" tabindex="-1">家人之震 <a class="header-anchor" href="#家人之震" aria-label="Permalink to “家人之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>黃牛騂犢，東行折角。冀得百祥，反亡我囊。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為牛犢。震為玄黃。故曰黃牛。坎赤故曰騂犢。艮為角，震東坎破，故東行折角。震為百、為祥，坤為囊，坤初變陽，囊之形毀矣，故曰亡。</p><h3 id="家人之艮" tabindex="-1">家人之艮 <a class="header-anchor" href="#家人之艮" aria-label="Permalink to “家人之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>路多枳棘，步刺我足。不利旅客，為心作毒。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《艮》。</p><h3 id="家人之漸" tabindex="-1">家人之漸 <a class="header-anchor" href="#家人之漸" aria-label="Permalink to “家人之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>執斧破薪，使媒求婦。和合二姓，親御飲酒。召彼鄰裡，公姑悅喜。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮手為執，伏兌為斧，巽為薪，坎為破，故曰破薪。《詩豳風》：&quot;伐柯如何，匪斧不克；娶妻如何，匪媒不得&quot;。坎為合、為媒，艮為求，巽為婦，坤為姓，數二，坎入坤，故曰和合二姓。坎為酒。按：《禮昏義》：&quot;婿親御婦車三週，共牢而食，合巹而酳。&quot;親御、飲酒，皆古禮也。艮為鄰裡，巽為母，震為公、為悅喜。○召彼，宋元本作居比，依汲古。飲酒，依《小過》之《益》校，各本皆作斯酒，斯，析也，巹，半瓢也。以一瓢破為二，各持其一以酳，故曰斯酒，亦可從。</p><h3 id="家人之歸妹" tabindex="-1">家人之歸妹 <a class="header-anchor" href="#家人之歸妹" aria-label="Permalink to “家人之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>駕車出門，順時宜西。福佑我身，安寧無患。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為駕、為車，伏艮為門，兌為西，卦春夏秋冬皆備，故曰順時。</p><h3 id="家人之豐" tabindex="-1">家人之豐 <a class="header-anchor" href="#家人之豐" aria-label="Permalink to “家人之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>日新東升，魁杓為禍。僕臺為秦，使我久坐。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為日、為新，震為東、為升、為魁杓，又伏艮為星，卦數七，鬥七星故曰魁杓。魁杓者，鬥柄也。鬥柄所指，四時以成，《易》六二、九四皆不吉，皆曰日中見鬥，故曰為禍。又魁杓即魁罡也。亦謂天罡。《渙》之《比》雲&quot;行觸天罡，馬死車傷&quot;，《睽》之《漸》曰&quot;魁罡所當，初為敗殃&quot;。○升，宋元本作從，依汲古。</p><h3 id="家人之旅" tabindex="-1">家人之旅 <a class="header-anchor" href="#家人之旅" aria-label="Permalink to “家人之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>山陵邱墓，魂魄室屋。精光竭盡，長臥無覺。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為山邱、為室屋，震為精光，震伏風隕，故曰竭盡。艮為臥。○魄，汲古作空，依宋元本。</p><h3 id="家人之巽" tabindex="-1">家人之巽 <a class="header-anchor" href="#家人之巽" aria-label="Permalink to “家人之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>孩子貪餌，為利所說。探釜把瓶，爛其臂手。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為孩子、為餌，巽為利，震為說、為釜瓶，巽為爛，艮為手、為臂，言孩子無知，貪餅餌微利，探手釜瓶為沸湯所傷也。○第三句宋元本作探把釜瓶，依汲古。臂手，汲古作手臂，依宋元本。</p><h3 id="家人之兌" tabindex="-1">家人之兌 <a class="header-anchor" href="#家人之兌" aria-label="Permalink to “家人之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>何材待時，閉門獨愁。蚯蚓冬行，解我無憂。桑蠶不得，女紅不成。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>何荷同。伏艮為材、為負。何為待、為時，故何材待時。艮為門，坎為閉、為愁，坎孤，故閉門獨愁。互巽為蚯蚓，伏坎為冬，震為解，故無憂。巽為桑、為蠶、為工，故曰女紅。紅同工。《漢書酈食其傳》：&quot;紅女下機&quot;，師古讀紅為工，兌毀故無成。○愁，汲古作悲，不韻，非，依宋元本。紅，宋元作功，義同，依汲古。</p><h3 id="家人之渙" tabindex="-1">家人之渙 <a class="header-anchor" href="#家人之渙" aria-label="Permalink to “家人之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>解商驚惶，散我衣裝，君不安邦。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為解、為商旅、為驚惶、為衣裝、為君，艮為邦，正反震故不安。○裝，汲古作裳，依宋元本。</p><h3 id="家人之節" tabindex="-1">家人之節 <a class="header-anchor" href="#家人之節" aria-label="Permalink to “家人之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>害政養賊，背主人愆。跛行不安，國危為患。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坤為政，坎折坤，故曰害政。坎為賊，震為主，艮為背、為覆震，故曰背主。震為足，兌折故跛行。艮為國，坎為危。○國危為患，汲古作國為危患，依宋元本。</p><h3 id="家人之中孚" tabindex="-1">家人之中孚 <a class="header-anchor" href="#家人之中孚" aria-label="Permalink to “家人之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>禍走患伏，喜為我福。兇惡消亡，災害不作。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為伏，兌為禍患，震行，故曰禍走患伏。震為喜、為福，兌剛魯故曰兇惡毀折，故曰災害。兌覆為巽，巽敝漏，故曰兇惡消亡，曰災害不作。○亡，元本作去，依宋本、汲古。</p><h3 id="家人之小過" tabindex="-1">家人之小過 <a class="header-anchor" href="#家人之小過" aria-label="Permalink to “家人之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>老馬為駒，病雞不雛。三雌獨宿，利在山北。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為馬，艮為壽，故曰老馬，兌少故曰駒。巽為雞、為疾，故曰病雞。兌為雛、為雌，震數三，故曰三雌。巽為獨、為伏，故曰獨宿。巽為利，上震為覆艮，故曰山北。《中孚》二至四艮覆曰鳴鶴在陰，在山陰也，茲曰山北，義同。</p><h3 id="家人之既濟" tabindex="-1">家人之既濟 <a class="header-anchor" href="#家人之既濟" aria-label="Permalink to “家人之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>播天舞，光地乳。神所守，樂無咎。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此皆用半象。光地乳，各本皆作地撓亂，依《剝》之《兌》校。</p><h3 id="家人之未濟" tabindex="-1">家人之未濟 <a class="header-anchor" href="#家人之未濟" aria-label="Permalink to “家人之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>異國殊俗，情不相得。金木為仇，酋賊擅殺。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>第四句宋元本作酉賊檀榖，汲古作酋長擅役，茲酋字、擅字依汲古，賊字依宋元本。殺字，依《夬》之《比》校。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
